import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function replaceUnique(output, from, to, label) {
  const first = output.indexOf(from);
  const last = output.lastIndexOf(from);
  if (first < 0 || first !== last)
    throw new Error(`MS route cancellation patch failed: ${label}`);
  return output.replace(from, to);
}

const FRONTEND_MARKER = "async function submitCancelMsRoute(event)";
const STYLE_MARKER = "/* MS route cancellation controls */";

export function patchMsRouteCancellationFrontend(source) {
  let output = String(source || "");
  if (output.includes(FRONTEND_MARKER)) return output;

  output = replaceUnique(output, `  archiveLoaded: false,\n};`, `  archiveLoaded: false,\n  cancelledRouteIds: new Set(),\n};`, "frontend cancellation state");
  output = replaceUnique(output, `  document.addEventListener("click", (event) => {\n    const button = event.target.closest("[data-pending-proof]");\n    if (button) openPendingParcels(button.dataset.pendingProof, button.dataset.pendingDay);\n  });`, `  document.addEventListener("click", (event) => {\n    const pendingButton = event.target.closest("[data-pending-proof]");\n    if (pendingButton)\n      openPendingParcels(\n        pendingButton.dataset.pendingProof,\n        pendingButton.dataset.pendingDay,\n      );\n    const cancelButton = event.target.closest("[data-cancel-ms-route]");\n    if (cancelButton) openCancelMsRoute(cancelButton.dataset.cancelMsRoute);\n  });`, "frontend cancel button delegation");
  output = replaceUnique(output, `    state.currentRows = Array.isArray(result?.rows) ? result.rows : [];`, `    state.currentRows = Array.isArray(result?.rows) ? result.rows : [];\n    for (const row of state.currentRows) {\n      const routeId = String(row.id || row.proofId || "");\n      if (routeId && row.queueCancelledAt) state.cancelledRouteIds.add(routeId);\n    }`, "frontend absorb persisted cancellations");
  output = replaceUnique(output, `  state.archiveLoaded = false;\n  state.rows = [];`, `  state.archiveLoaded = false;\n  state.cancelledRouteIds.clear();\n  state.rows = [];`, "frontend clear cancellation memory on HUB change");
  output = replaceUnique(output, `  const unloadingState = Number(row.unloadingState),`, `  const routeId = String(row.id || row.proofId || ""),\n    cancelled = Boolean(\n      row.queueCancelledAt ||\n        (routeId && state.cancelledRouteIds?.has(routeId)),\n    ),\n    unloadingState = Number(row.unloadingState),`, "queue cancellation state");
  output = replaceUnique(output, `    active = Boolean(routeArrival) && !done && ageHours <= 12;`, `    active = Boolean(routeArrival) && !done && !cancelled && ageHours <= 12;`, "cancelled route leaves current queue");
  output = replaceUnique(output, `  return {\n    active,\n    done,\n    started,\n    expired: Boolean(routeArrival) && !done && ageHours > 12,\n    ageHours,\n  };`, `  return {\n    active,\n    done,\n    started,\n    cancelled,\n    expired: Boolean(routeArrival) && !done && !cancelled && ageHours > 12,\n    ageHours,\n  };`, "queue cancellation result");
  output = replaceUnique(output, `function isCompletedToday(row, now = new Date()) {\n  if ((!isDestination(row) && !isDrop(row)) || Number(row.unloadingState) !== 2)`, `function isCompletedToday(row, now = new Date()) {\n  if (row.queueCancelledAt) return false;\n  if ((!isDestination(row) && !isDrop(row)) || Number(row.unloadingState) !== 2)`, "cancelled route is not daily completion");
  output = replaceUnique(output, `(state.summary === "origin" && isOrigin(row) && !queue.done) ||`, `(state.summary === "origin" && isOrigin(row) && !queue.done && !queue.cancelled) ||`, "cancelled origin leaves summary");
  output = replaceUnique(output, `(state.summary === "drop" && isDrop(row) && !queue.done);`, `(state.summary === "drop" && isDrop(row) && !queue.done && !queue.cancelled);`, "cancelled drop leaves summary");
  output = replaceUnique(output, `  const workStatus = isDestination(row)\n    ? row.loadStatus || status.label`, `  const workStatus = q.cancelled\n    ? "ยกเลิกเส้นทาง"\n    : isDestination(row)\n      ? row.loadStatus || status.label`, "desktop cancelled work status");
  output = replaceUnique(output, `  const queueText = q.done\n    ? "เสร็จแล้ว"`, `  const queueText = q.cancelled\n    ? \`ยกเลิกโดย \${row.queueCancelledBy || "-"} · \${shortDateTime(row.queueCancelledAt)}\`\n    : q.done\n      ? "เสร็จแล้ว"`, "desktop cancelled queue label");
  output = replaceUnique(output, `<div class="work-badge \${q.expired ? "expired" : status.key}">`, `<div class="work-badge \${q.cancelled ? "cancelled" : q.expired ? "expired" : status.key}">`, "desktop cancelled badge class");
  output = replaceUnique(output, `<td><div class="people-summary"><strong>\${esc(row.supplier || "-")}</strong><span>\${esc(row.driverName || "ไม่พบชื่อคนขับ")}</span>\${row.driverPhone ? \`<a class="phone-chip" href="tel:\${esc(row.driverPhone)}">\${esc(row.driverPhone)}</a>\` : ""}</div></td>`, `<td><div class="people-summary"><strong>\${esc(row.supplier || "-")}</strong><span>\${esc(row.driverName || "ไม่พบชื่อคนขับ")}</span>\${row.driverPhone ? \`<a class="phone-chip" href="tel:\${esc(row.driverPhone)}">\${esc(row.driverPhone)}</a>\` : ""}\${q.active ? \`<button type="button" class="cancel-route-button" data-cancel-ms-route="\${esc(row.id || "")}">ยกเลิกเส้นทาง</button>\` : ""}</div></td>`, "desktop cancel route button");
  output = replaceUnique(output, `  const workStatus = isDestination(row)\n    ? row.loadStatus || status.label\n    : isDrop(row)`, `  const workStatus = q.cancelled\n    ? "ยกเลิกเส้นทาง"\n    : isDestination(row)\n      ? row.loadStatus || status.label\n      : isDrop(row)`, "mobile cancelled work status");
  output = replaceUnique(output, `    queueText = isDrop(row)\n      ? drop.onwardMinutes === null`, `    queueText = q.cancelled\n      ? \`ยกเลิกโดย \${row.queueCancelledBy || "-"} · \${shortDateTime(row.queueCancelledAt)}\`\n      : isDrop(row)\n        ? drop.onwardMinutes === null`, "mobile cancelled queue label");
  output = replaceUnique(output, `<div class="compact-party"><div><span>บริษัทซัพ</span><strong>\${esc(row.supplier || "ไม่พบชื่อบริษัทซัพ")}</strong></div><div><span>คนขับรถ</span><strong>\${esc(row.driverName || "ไม่พบชื่อคนขับ")}</strong></div>\${row.driverPhone ? \`<a class="compact-phone" href="tel:\${esc(row.driverPhone)}"><span>โทร</span>\${esc(row.driverPhone)}</a>\` : ""}</div>`, `<div class="compact-party"><div><span>บริษัทซัพ</span><strong>\${esc(row.supplier || "ไม่พบชื่อบริษัทซัพ")}</strong></div><div><span>คนขับรถ</span><strong>\${esc(row.driverName || "ไม่พบชื่อคนขับ")}</strong></div>\${row.driverPhone ? \`<a class="compact-phone" href="tel:\${esc(row.driverPhone)}"><span>โทร</span>\${esc(row.driverPhone)}</a>\` : ""}\${q.active ? \`<button type="button" class="cancel-route-button compact-cancel-route" data-cancel-ms-route="\${esc(row.id || "")}">ยกเลิกเส้นทาง</button>\` : ""}</div>`, "mobile cancel route button");
  output = replaceUnique(output, `    queueStatus: q.expired\n      ? "ตัดคิวเกิน 12 ชั่วโมง"`, `    queueStatus: q.cancelled\n      ? "ยกเลิกเส้นทาง"\n      : q.expired\n        ? "ตัดคิวเกิน 12 ชั่วโมง"`, "export cancelled queue status");
  output = replaceUnique(output, `    loadStatus: row.loadStatus || "",`, `    queueCancelledAt: exportThaiDate(row.queueCancelledAt),\n    queueCancelledBy: row.queueCancelledBy || "",\n    queueCancelReason: row.queueCancelReason || "",\n    loadStatus: row.loadStatus || "",`, "export cancellation audit fields");
  output = replaceUnique(output, `function normalizeVehicle(value) {`, `let cancelRouteTarget = null;\n\nfunction ensureCancelMsRouteDialog() {\n  let dialog = el("cancel-ms-route-dialog");\n  if (dialog) return dialog;\n  dialog = document.createElement("dialog");\n  dialog.id = "cancel-ms-route-dialog";\n  dialog.className = "cancel-ms-route-dialog";\n  dialog.innerHTML = \`\n    <form method="dialog" class="cancel-route-form">\n      <div class="cancel-route-icon">!</div>\n      <h3>ยืนยันยกเลิกเส้นทาง</h3>\n      <p id="cancel-route-detail"></p>\n      <div class="cancel-route-warning">เส้นทางจะถูกตัดออกจากคิวของระบบนี้เท่านั้น และจะไม่แก้สถานะใน MS</div>\n      <label>รหัสจัดการ / PIN\n        <input id="cancel-route-pin" type="password" inputmode="numeric" autocomplete="current-password" required>\n      </label>\n      <div id="cancel-route-error" class="cancel-route-error hidden"></div>\n      <div class="cancel-route-actions">\n        <button type="button" class="cancel-route-back" data-cancel-route-close>ไม่ยกเลิก</button>\n        <button type="submit" class="cancel-route-confirm">ยืนยันยกเลิกเส้นทาง</button>\n      </div>\n    </form>\`;\n  document.body.append(dialog);\n  dialog.querySelector("[data-cancel-route-close]").onclick = () => dialog.close();\n  dialog.querySelector("form").onsubmit = submitCancelMsRoute;\n  dialog.addEventListener("close", () => {\n    el("cancel-route-pin").value = "";\n    el("cancel-route-error").classList.add("hidden");\n    cancelRouteTarget = null;\n  });\n  return dialog;\n}\n\nfunction openCancelMsRoute(routeId) {\n  const id = String(routeId || "");\n  const row = state.currentRows.find((item) => String(item.id || "") === id);\n  if (!row || !queueInfo(row).active)\n    return toast("เส้นทางนี้ไม่ได้อยู่ในคิวปัจจุบันแล้ว", true);\n  cancelRouteTarget = { id, proofId: row.proofId || "", routeName: row.routeName || "" };\n  const dialog = ensureCancelMsRouteDialog();\n  el("cancel-route-detail").textContent = \`\${row.proofId || id} · \${row.routeName || "ไม่พบชื่อเส้นทาง"}\`;\n  el("cancel-route-pin").value = "";\n  el("cancel-route-error").classList.add("hidden");\n  dialog.showModal();\n  setTimeout(() => el("cancel-route-pin").focus(), 0);\n}\n\nfunction applyCancelledRouteLocal(routeId, result) {\n  const id = String(routeId || "");\n  const patchRow = (row) => String(row.id || "") === id ? { ...row, queueCancelledAt: result.cancelledAt, queueCancelledBy: result.cancelledBy, queueCancelReason: result.reason || "ยกเลิกเส้นทาง" } : row;\n  state.cancelledRouteIds.add(id);\n  state.currentRows = state.currentRows.map(patchRow);\n  state.archiveRows = state.archiveRows.map(patchRow);\n  state.rows = state.rows.map(patchRow);\n}\n\nasync function submitCancelMsRoute(event) {\n  event.preventDefault();\n  const target = cancelRouteTarget;\n  const pin = el("cancel-route-pin").value;\n  const confirmButton = event.currentTarget.querySelector(".cancel-route-confirm");\n  const errorBox = el("cancel-route-error");\n  if (!target || !pin) {\n    errorBox.textContent = "กรุณาใส่รหัสจัดการเพื่อยืนยัน";\n    errorBox.classList.remove("hidden");\n    return;\n  }\n  try {\n    confirmButton.disabled = true;\n    errorBox.classList.add("hidden");\n    const result = await apiPost("cancelMsRoute", { branch: state.branch, routeId: target.id, pin });\n    applyCancelledRouteLocal(target.id, result);\n    el("cancel-ms-route-dialog").close();\n    render();\n    toast(\`ยกเลิกเส้นทาง \${target.proofId || target.id} และตัดออกจากคิวแล้ว\`);\n  } catch (error) {\n    errorBox.textContent = error.message;\n    errorBox.classList.remove("hidden");\n  } finally {\n    confirmButton.disabled = false;\n  }\n}\n\nfunction normalizeVehicle(value) {`, "frontend cancellation confirmation dialog");
  return output;
}

export function patchMsRouteCancellationStyle(source) {
  const output = String(source || "");
  if (output.includes(STYLE_MARKER)) return output;
  return `${output.trimEnd()}\n\n${STYLE_MARKER}\n.cancel-route-button{margin-top:8px;border:1px solid #b3261e;background:#fff;color:#9b1c1c;border-radius:8px;padding:7px 10px;font:inherit;font-weight:700;cursor:pointer}.cancel-route-button:hover{background:#fff1f1}.cancel-route-button:disabled{opacity:.55;cursor:wait}.compact-cancel-route{width:100%;grid-column:1/-1}.work-badge.cancelled{background:#fff1f1;color:#9b1c1c;border-color:#efb5b5}.cancel-ms-route-dialog{border:0;border-radius:16px;padding:0;max-width:480px;width:calc(100% - 28px);box-shadow:0 24px 80px #0004}.cancel-ms-route-dialog::backdrop{background:#0008}.cancel-route-form{padding:24px;display:grid;gap:14px}.cancel-route-form h3{margin:0;font-size:22px}.cancel-route-form p{margin:0;font-weight:700;line-height:1.5}.cancel-route-icon{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#fff1f1;color:#b3261e;font-size:26px;font-weight:900}.cancel-route-warning{padding:12px 14px;border-radius:10px;background:#fff8dc;border:1px solid #efd36b;line-height:1.5}.cancel-route-form label{display:grid;gap:7px;font-weight:700}.cancel-route-form input{width:100%;min-height:46px;border:1px solid #b8bec6;border-radius:9px;padding:0 12px;font-size:18px}.cancel-route-error{padding:10px 12px;border-radius:8px;background:#fff0f0;color:#a31313;font-weight:700}.cancel-route-actions{display:flex;gap:10px;justify-content:flex-end}.cancel-route-actions button{min-height:44px;border-radius:9px;padding:0 14px;font-weight:700;cursor:pointer}.cancel-route-back{border:1px solid #aeb4bb;background:#fff;color:#222}.cancel-route-confirm{border:1px solid #9b1c1c;background:#b3261e;color:#fff}@media(max-width:600px){.cancel-route-actions{display:grid;grid-template-columns:1fr}.cancel-route-actions button{width:100%}}\n`;
}

export function patchMsRouteCancellationWorker(source) {
  let output = String(source || "");
  if (output.includes("async function cancelMsRoute(body, actor, env)")) return output;
  output = replaceUnique(output, `  const actor = await verify(body.token, env);\n  if (action === "import") return ok(await importRows(body, actor, env));`, `  const actor = await verify(body.token, env);\n  if (action === "cancelMsRoute")\n    return ok(await cancelMsRoute(body, actor, env));\n  if (action === "import") return ok(await importRows(body, actor, env));`, "backend cancel action route");
  output = replaceUnique(output, `    const rows = Array.isArray(live.rows)\n      ? live.rows\n      : (\n          await env.DB.prepare("SELECT * FROM ms_routes WHERE hub=?")\n            .bind(branch)\n            .all()\n        ).results.map(output);`, `    const rows = Array.isArray(live.rows)\n      ? live.rows\n      : await applyRouteCancellationsToRows(\n          env,\n          branch,\n          (\n            await env.DB.prepare("SELECT * FROM ms_routes WHERE hub=?")\n              .bind(branch)\n              .all()\n          ).results.map(output),\n        );`, "backend fallback cancellation overlay");
  output = replaceUnique(output, `  const oldRows = (\n    await env.DB.prepare("SELECT * FROM ms_routes WHERE hub=?")\n      .bind(branch)\n      .all()\n  ).results;\n  const oldById = new Map(oldRows.map((row) => [row.id, row]));`, `  const [oldRowsResult, cancellationResult] = await Promise.all([\n    env.DB.prepare("SELECT * FROM ms_routes WHERE hub=?").bind(branch).all(),\n    env.DB.prepare(\n      "SELECT route_id,proof_id,cancelled_at,cancelled_by,reason FROM ms_route_cancellations WHERE hub=? AND active=1",\n    )\n      .bind(branch)\n      .all(),\n  ]);\n  const oldRows = oldRowsResult.results;\n  const cancellationById = new Map(\n    cancellationResult.results.map((row) => [String(row.route_id), row]),\n  );\n  const oldById = new Map(oldRows.map((row) => [row.id, row]));`, "load cancellations only when syncMs runs");
  output = replaceUnique(output, `      arrivedParcels: values[28],\n      arrivedBags: values[29],\n    };\n    prepared.push({ id, values, snapshot });`, `      arrivedParcels: values[28],\n      arrivedBags: values[29],\n    };\n    const cancellation = cancellationById.get(String(id));\n    if (\n      cancellation &&\n      (!cancellation.proof_id || !snapshot.proofId || String(cancellation.proof_id) === String(snapshot.proofId))\n    ) {\n      snapshot.queueCancelledAt = cancellation.cancelled_at || "";\n      snapshot.queueCancelledBy = cancellation.cancelled_by || "";\n      snapshot.queueCancelReason = cancellation.reason || "ยกเลิกเส้นทาง";\n    }\n    prepared.push({ id, values, snapshot });`, "overlay cancellation on changed MS snapshots");
  output = replaceUnique(output, `  const rows = [...latest.values()];`, `  const rows = await applyRouteCancellationsToRows(\n    env,\n    hub,\n    [...latest.values()],\n  );`, "archive cancellation overlay");
  output = replaceUnique(output, `  return (\n    (attendance === "ปลายทาง" || attendance === "จุดดรอป") &&\n    Number(row?.unloadingState) === 2 &&`, `  return (\n    !row?.queueCancelledAt &&\n    (attendance === "ปลายทาง" || attendance === "จุดดรอป") &&\n    Number(row?.unloadingState) === 2 &&`, "cancelled route excluded from daily completion cache");
  output = replaceUnique(output, `async function syncMs(body, actor, env) {`, `async function confirmActionPin(actor, pin, env) {\n  const user = await env.DB.prepare(\n    "SELECT password_hash,active FROM users WHERE username=?",\n  )\n    .bind(actor.username)\n    .first();\n  if (!user || Number(user.active) !== 1 || !(await passMatch(actor.username, pin, user.password_hash, env)))\n    fail("รหัสจัดการไม่ถูกต้อง กรุณาตรวจสอบแล้วลองใหม่", "INVALID_CONFIRMATION_PIN", 401);\n}\n\nfunction routeCancellationMeta(row) {\n  return { queueCancelledAt: row.cancelled_at || "", queueCancelledBy: row.cancelled_by || "", queueCancelReason: row.reason || "ยกเลิกเส้นทาง" };\n}\n\nasync function activeRouteCancellations(env, hub) {\n  return (await env.DB.prepare("SELECT route_id,proof_id,cancelled_at,cancelled_by,reason FROM ms_route_cancellations WHERE hub=? AND active=1").bind(hub).all()).results;\n}\n\nasync function applyRouteCancellationsToRows(env, hub, rows) {\n  const cancellations = await activeRouteCancellations(env, hub);\n  if (!cancellations.length) return rows || [];\n  const byId = new Map(cancellations.map((row) => [String(row.route_id), row]));\n  return (rows || []).map((row) => {\n    const cancellation = byId.get(String(row.id || row.routeId || ""));\n    if (!cancellation || (cancellation.proof_id && row.proofId && String(cancellation.proof_id) !== String(row.proofId))) return row;\n    return { ...row, ...routeCancellationMeta(cancellation) };\n  });\n}\n\nasync function markCancelledInLiveCache(env, hub, routeId, proofId, meta) {\n  const cache = await env.DB.prepare("SELECT rows_json FROM ms_live_cache WHERE hub=?").bind(hub).first();\n  if (!cache) return false;\n  let parsed;\n  try { parsed = JSON.parse(cache.rows_json || "[]"); } catch { return false; }\n  const legacy = Array.isArray(parsed);\n  const rows = legacy ? parsed : Array.isArray(parsed?.rows) ? parsed.rows : [];\n  let changed = false;\n  const nextRows = rows.map((row) => {\n    const idMatch = String(row.id || row.routeId || "") === String(routeId);\n    const proofMatch = !proofId || !row.proofId || String(row.proofId) === String(proofId);\n    if (!idMatch || !proofMatch) return row;\n    changed = true;\n    return { ...row, ...meta };\n  });\n  const completedRows = legacy ? [] : (Array.isArray(parsed.completedRows) ? parsed.completedRows : []).filter((row) => String(row.id || row.routeId || "") !== String(routeId));\n  const completedChanged = !legacy && completedRows.length !== (Array.isArray(parsed.completedRows) ? parsed.completedRows.length : 0);\n  if (!changed && !completedChanged) return false;\n  const payload = legacy ? nextRows : { ...parsed, rows: nextRows, completedRows };\n  await env.DB.prepare("UPDATE ms_live_cache SET rows_json=? WHERE hub=?").bind(JSON.stringify(payload), hub).run();\n  return true;\n}\n\nasync function cancelMsRoute(body, actor, env) {\n  const hub = pickBranch(actor, body.branch);\n  const routeId = text(body.routeId, 200);\n  if (!routeId) fail("ไม่พบรหัสเส้นทาง", "INVALID_ROUTE", 400);\n  await confirmActionPin(actor, body.pin, env);\n  const route = await env.DB.prepare("SELECT id,proof_id,route_name,attendance_type,actual_arrival_at,actual_departure_at,unloading_state,schedule_kit_arrival_at,schedule_tbr_arrival_at FROM ms_routes WHERE hub=? AND id=?").bind(hub, routeId).first();\n  if (!route) fail("ไม่พบเส้นทางนี้ใน HUB ปัจจุบัน", "ROUTE_NOT_FOUND", 404);\n  const attendance = normalizeMsAttendance(route.attendance_type);\n  const done = attendance === "ปลายทาง" ? Number(route.unloading_state) === 2 : attendance === "จุดดรอป" ? Number(route.unloading_state) === 2 && Boolean(route.actual_departure_at) : Boolean(route.actual_departure_at);\n  if (done) fail("เส้นทางนี้ดำเนินการเสร็จแล้ว จึงไม่สามารถยกเลิกจากคิวได้", "ROUTE_ALREADY_DONE", 409);\n  const effectiveArrival = earliestDate(route.actual_arrival_at, route.schedule_kit_arrival_at, route.schedule_tbr_arrival_at);\n  if (!route.actual_arrival_at || !effectiveArrival || Date.now() - Date.parse(effectiveArrival) > 12 * 60 * 60 * 1000) fail("เส้นทางนี้ไม่ได้อยู่ในคิวปัจจุบันแล้ว", "ROUTE_NOT_ACTIVE", 409);\n  const existing = await env.DB.prepare("SELECT proof_id,cancelled_at,cancelled_by,reason,active FROM ms_route_cancellations WHERE hub=? AND route_id=?").bind(hub, routeId).first();\n  if (Number(existing?.active) === 1 && (!existing.proof_id || String(existing.proof_id) === String(route.proof_id || ""))) {\n    const meta = routeCancellationMeta(existing);\n    await markCancelledInLiveCache(env, hub, routeId, route.proof_id || "", meta);\n    return { hub, routeId, proofId: route.proof_id || "", routeName: route.route_name || "", cancelledAt: meta.queueCancelledAt, cancelledBy: meta.queueCancelledBy, reason: meta.queueCancelReason, alreadyCancelled: true };\n  }\n  const now = new Date().toISOString();\n  const reason = "ยกเลิกเส้นทาง";\n  await env.DB.prepare("INSERT INTO ms_route_cancellations(hub,route_id,proof_id,route_name,cancelled_at,cancelled_by,reason,active) VALUES(?,?,?,?,?,?,?,1) ON CONFLICT(hub,route_id) DO UPDATE SET proof_id=excluded.proof_id,route_name=excluded.route_name,cancelled_at=excluded.cancelled_at,cancelled_by=excluded.cancelled_by,reason=excluded.reason,active=1").bind(hub, routeId, route.proof_id || "", route.route_name || "", now, actor.username, reason).run();\n  const meta = { queueCancelledAt: now, queueCancelledBy: actor.username, queueCancelReason: reason };\n  await markCancelledInLiveCache(env, hub, routeId, route.proof_id || "", meta);\n  await audit(env, "CANCEL_MS_ROUTE", routeId, JSON.stringify({ hub, proofId: route.proof_id || "", routeName: route.route_name || "", reason }), actor.username);\n  return { hub, routeId, proofId: route.proof_id || "", routeName: route.route_name || "", cancelledAt: now, cancelledBy: actor.username, reason, alreadyCancelled: false };\n}\n\nasync function syncMs(body, actor, env) {`, "backend cancellation helpers");
  return output;
}

export async function patchMsRouteCancellationFiles(frontendTarget) {
  const styleTarget = join(dirname(frontendTarget), "style.css");
  const [frontend, style] = await Promise.all([readFile(frontendTarget, "utf8"), readFile(styleTarget, "utf8")]);
  await Promise.all([writeFile(frontendTarget, patchMsRouteCancellationFrontend(frontend), "utf8"), writeFile(styleTarget, patchMsRouteCancellationStyle(style), "utf8")]);
}

const invokedPath = process.argv[1] ? fileURLToPath(import.meta.url) === process.argv[1] : false;
if (invokedPath) {
  const frontendTarget = process.argv[2];
  const workerTarget = process.argv[3];
  if (!frontendTarget || !workerTarget) throw new Error("Usage: node patch-ms-route-cancellation.mjs <staged-ms.js> <worker-index.js>");
  const [frontend, style, worker] = await Promise.all([readFile(frontendTarget, "utf8"), readFile(join(dirname(frontendTarget), "style.css"), "utf8"), readFile(workerTarget, "utf8")]);
  await Promise.all([writeFile(frontendTarget, patchMsRouteCancellationFrontend(frontend), "utf8"), writeFile(join(dirname(frontendTarget), "style.css"), patchMsRouteCancellationStyle(style), "utf8"), writeFile(workerTarget, patchMsRouteCancellationWorker(worker), "utf8")]);
}
